def apply(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    rows=inputs.get('semantic_answers',[])
    if isinstance(rows,dict):
        value=rows.get('answers')
        if isinstance(value,list):
            rows=value
        elif isinstance(value,dict):
            rows=list(value.values())
        else:
            rows=list(rows.values())
    if not isinstance(rows,list):
        rows=[]
    answered=set()
    by_id={}
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            answered.add(row.get('id'))
            by_id[row.get('id')]=row
    all_ids=[]
    positions={}
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        all_ids.append(uid)
        positions[uid]=i
        i+=1
    queries=[]
    scouts=[('disclosure_locator_v2','locate_disclosure_windows_v2'),('disposal_locator_v2','locate_disposal_windows_v2')]
    for qid,operation in scouts:
        if qid not in answered and all_ids:
            queries.append({'id':qid,'operation':operation,'unit_ids':all_ids})
    families=[('disclosure_locator_v2','disclosure',['disclosure_effect_v2','recipient_employees_v2','controlled_entity_employees_v2','recipient_contractors_v2','recipient_consultants_v2','recipient_agents_v2','recipient_professional_advisers_v2','need_to_know_v2','extent_necessary_v2','recipient_confidentiality_v2']),('disposal_locator_v2','disposal',['disposal_action_connection_v2','return_trigger_v2','destroy_trigger_v2','return_material_scope_v2','destroy_material_scope_v2','retention_effect_v2','retention_basis_v2','retention_material_scope_v2'])]
    for scout_id,prefix,operations in families:
        scout=by_id.get(scout_id)
        if not isinstance(scout,dict) or scout.get('choice')!='candidate_found':
            continue
        selected=[]
        evidence=scout.get('evidence',[])
        if isinstance(evidence,dict):
            evidence=[evidence]
        for item in evidence:
            if isinstance(item,dict) and item.get('unit_id') in positions:
                pos=positions[item.get('unit_id')]
                if pos not in selected:
                    selected.append(pos)
        selected=sorted(selected)
        groups=[]
        for pos in selected:
            if not groups or pos-groups[len(groups)-1][len(groups[len(groups)-1])-1]>2:
                groups.append([pos])
            else:
                groups[len(groups)-1].append(pos)
        for group in groups:
            start=max(0,group[0]-1)
            stop=min(len(spans)-1,group[len(group)-1]+1)
            unit_ids=[]
            j=start
            while j<=stop:
                unit_ids.append(spans[j].get('id'))
                j+=1
            suffix=str(unit_ids[0])+'_'+str(unit_ids[len(unit_ids)-1])
            for operation in operations:
                qid=prefix+'_'+operation+'__'+suffix
                if qid not in answered:
                    queries.append({'id':qid,'operation':operation,'unit_ids':unit_ids})
    return {'queries':queries}

def normalized_text(x):
    if not isinstance(x,str):
        x=str(x)
    return x.casefold().strip()

def has_any_phrase(t,phrases):
    for p in phrases:
        if p in t:
            return True
    return False

def is_disclosure_permission_candidate(t):
    if 'confidential information' not in t:
        return False
    if 'disclos' not in t and 'access' not in t:
        return False
    if 'employee' not in t and 'contractor' not in t:
        return False
    return has_any_phrase(t,['may disclose','may be disclosed','permitted to disclose','restrict access','disclosed only to','except to'])

def is_recipient_definition(t):
    return has_any_phrase(t,['recipient” shall mean','recipient" shall mean','recipient shall mean'])

def has_any(t,xs):
    for x in xs:
        if x in t:
            return True
    return False

def has_recipient_role(t):
    return has_any(t,['employee','contractor','consultant','agent','representative','official','professional adviser','professional advisor'])

def is_major_clause(t):
    return re.match(r'^\s*\d+\.\s',t,re.I) is not None

def is_disclosure_direct(t):
    if not has_recipient_role(t):
        return False
    if 'confidential information' not in t and 'such confidential information' not in t and 'contents of the confidential information' not in t:
        return False
    return has_any(t,['may disclose','may be disclosed','disclosed only to','restrict disclosure','restrict access','except in confidence','except to such'])

def is_disclosure_header(t):
    if 'confidential information' not in t:
        return False
    if not has_any(t,['may disclose','may be disclosed']):
        return False
    return t.endswith(':') or ' disclose the confidential information to:' in t

def has_disposal_action(t):
    return has_any(t,['return','returned']) and has_any(t,['destroy','destroyed','destruction'])

def has_disposal_trigger(t):
    return has_any(t,['termination','expiration','request','business relationship is not entered','completion of the purpose'])

def is_disposal_direct(t):
    if 'confidential information' not in t:
        return False
    return has_disposal_action(t) and has_disposal_trigger(t)

def is_disposal_header(t):
    if 'confidential information' not in t:
        return False
    return has_disposal_action(t) and t.endswith(':') and not has_disposal_trigger(t)

def governing_stem_index(spans,focus_index):
    j=focus_index-1
    floor=max(0,focus_index-8)
    while j>=floor:
        t=normalized_text(spans[j].get('text',''))
        if t.endswith(':') and 'confidential information' in t and has_any(t,['shall','may']):
            return j
        j-=1
    return None

def add_disclosure_queries(queries,seen,unit_ids,focus_id):
    key='disclosure_'+str(focus_id)
    if key in seen:
        return
    seen.add(key)
    queries.append({'id':'recipient_'+str(focus_id),'operation':'disclosure_recipient_bound','unit_ids':unit_ids})
    queries.append({'id':'need_'+str(focus_id),'operation':'need_to_know_requirement','unit_ids':unit_ids})
    queries.append({'id':'confidentiality_'+str(focus_id),'operation':'confidentiality_safeguard','unit_ids':unit_ids})

def add_disposal_query(queries,seen,unit_ids,focus_id):
    key='disposal_'+str(focus_id)
    if key in seen:
        return
    seen.add(key)
    queries.append({'id':'disposal_'+str(focus_id),'operation':'disposal_pattern','unit_ids':unit_ids})

def answer_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        answers=value.get('answers')
        if isinstance(answers,list):
            return answers
        if isinstance(answers,dict):
            return list(answers.values())
        return list(value.values())
    return []

def answered_query_ids(rows):
    out=set()
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            out.add(row.get('id'))
    return out

def answer_with_id(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return row
    return None

def evidence_unit_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    for item in answer.get('evidence',[]):
        if isinstance(item,dict):
            u=item.get('unit_id')
            if u not in out:
                out.append(u)
    return out

def term_has_constructor(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            todo.extend(item[1:])
    return False

def covered_disposal_units(source_output):
    out=set()
    if not isinstance(source_output,dict):
        return out
    for row in source_output.get('statements',[]):
        if isinstance(row,dict) and term_has_constructor(row.get('term'),'disposal_obligation'):
            for u in row.get('support_ids',[]):
                out.add(u)
    return out

def has_recipient_language(text):
    t=normalized_text(text)
    words=['employee','staff','personnel','consultant','agent','contractor','representative','official','adviser','advisor']
    for word in words:
        if word in t:
            return True
    return False

def has_confidentiality_followon(text):
    t=normalized_text(text)
    return ('confidential' in t or 'non-disclosure' in t or 'nondisclosure' in t) and ('employee' in t or 'staff' in t or 'personnel' in t or 'recipient' in t)

def has_disposal_trigger_language(text):
    t=normalized_text(text)
    words=['request','termination','expiration','completion','business relationship','service ends','service terminates']
    for word in words:
        if word in t:
            return True
    return False

def disclosure_focus_indices(spans,evidence_ids):
    positions={}
    i=0
    while i<len(spans):
        positions[spans[i].get('id')]=i
        i+=1
    candidates=[]
    for u in evidence_ids:
        if u in positions and has_recipient_language(spans[positions[u]].get('text','')):
            candidates.append(positions[u])
    extended=[]
    for p in candidates:
        q=p
        if p+1<len(spans) and has_confidentiality_followon(spans[p+1].get('text','')):
            q=p+1
        if q not in extended:
            extended.append(q)
    extended=sorted(extended)
    out=[]
    for p in extended:
        keep=True
        for q in extended:
            if q>p and q-p<=2:
                keep=False
        if keep:
            out.append(p)
    return out

def disclosure_window(spans,focus_index):
    start=max(0,focus_index-4)
    chosen=focus_index
    i=focus_index-1
    while i>=start:
        t=normalized_text(spans[i].get('text',''))
        if ('disclos' in t or 'restrict access' in t or 'restrict disclosure' in t) and ('information' in t or 'same' in t):
            chosen=i
        i-=1
    out=[]
    i=chosen
    while i<=focus_index:
        out.append(spans[i].get('id'))
        i+=1
    return out

def disposal_window(spans,focus_index):
    t=normalized_text(spans[focus_index].get('text',''))
    if ('return' in t or 'destroy' in t) and ('information' in t or 'copies' in t or 'materials' in t):
        return [spans[focus_index].get('id')]
    floor=max(0,focus_index-3)
    i=focus_index-1
    while i>=floor:
        p=normalized_text(spans[i].get('text',''))
        if ('return' in p or 'destroy' in p) and ('information' in p or 'copies' in p or 'materials' in p):
            return [spans[i].get('id'),spans[focus_index].get('id')]
        i-=1
    return [spans[focus_index].get('id')]

def answered_ids(rows):
    out=set()
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            out.add(row.get('id'))
    return out

def answer_by_id(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return row
    return None

def evidence_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    for item in answer.get('evidence',[]):
        if isinstance(item,dict):
            unit=item.get('unit_id')
            if unit not in out:
                out.append(unit)
    return out

ConstraintAcquire.source_program:
def any_phrase(t,xs):
    for x in xs:
        if x in t:
            return True
    return False

def has_word(t,p):
    return re.search(p,t,re.I) is not None

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term:
            return
    out.append({'term':term,'support_ids':support})

def add_once(xs,x):
    if x not in xs:
        xs.append(x)

def make_union(items):
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def make_condition(t):
    cs=[]
    if 'need to know' in t or 'need-to-know' in t or 'need-to know' in t:
        cs.append(['need_to_know','stated purpose'])
    if any_phrase(t,['bound by obligations of confidentiality','treat the confidential information as confidential','obliged by their contracts','obligated to protect','terms and conditions no less protective']):
        cs.append(['confidentiality_bound','source-stated confidentiality obligation'])
    if any_phrase(t,['only to the extent necessary','disclosure is necessary','as deemed necessary','reasonably necessary']):
        cs.append(['extent_necessary','source-stated purpose'])
    if not cs:
        return ['no_condition']
    v=cs[0]
    i=1
    while i<len(cs):
        v=['and_condition',v,cs[i]]
        i+=1
    return v

def permission_segment(t):
    marks=['may disclose','may share','internally share','restrict access','except in confidence','except to such']
    best=-1
    for m in marks:
        p=t.rfind(m)
        if p>best:
            best=p
    if best<0 and 'not to disclose' in t and ' except ' in t:
        best=t.rfind(' except ')
    return t[best:] if best>=0 else t

def recipient_terms(t):
    owner=['receiving_party']
    if any_phrase(t,["affiliates' officers","affiliates’ officers","affiliate's officers","affiliate’s officers"]):
        owner=['affiliates_of',['receiving_party']]
    xs=[]
    if has_word(t,r'\bemployees?\b'):
        xs.append(['employees_of',owner])
    if has_word(t,r'\bdirectors?\b'):
        xs.append(['directors_of',owner])
    if has_word(t,r'\bofficers?\b'):
        xs.append(['officers_of',owner])
    if any_phrase(t,['legal advisors','legal advisers','attorneys','legal counsel']):
        xs.append(['legal_advisors_of',owner])
    if any_phrase(t,['financial advisors','financial advisers']):
        xs.append(['financial_advisors_of',owner])
    if any_phrase(t,['professional advisors','professional advisers']):
        xs.append(['professional_advisors_of',owner])
    if has_word(t,r'\baccountants?\b'):
        xs.append(['accountants_of',owner])
    if has_word(t,r'\bconsultants?\b'):
        xs.append(['consultants_of',owner])
    if has_word(t,r'\bagents?\b'):
        xs.append(['agents_of',owner])
    if has_word(t,r'\bcontractors?\b'):
        xs.append(['independent_contractors_of',owner])
    if has_word(t,r'\blenders?\b'):
        xs.append(['lenders_of',owner])
    if 'internally share' in t and not xs:
        xs.append(['internal_personnel_of',['receiving_party']])
    if not xs and 'representatives' in t:
        xs.append(['representatives_of',['receiving_party']])
    if not xs and any_phrase(t,['third parties','third party']):
        xs.append(['third_parties'])
    return xs

def make_exceptions(t,perm):
    es=[]
    if any_phrase(t,['prior written consent','prior, written consent','prior written approval','prior written permission','expressly authorized in writing','express permission']):
        es.append(['authorization_exception','source-stated written authorization'])
    if any_phrase(t,['required to analyze','required to fulfil','required to fulfill']):
        es.append(['purpose_exception','source-stated required activity'])
    if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
        es.append(['cross_reference_exception','source-stated disclosure cross-reference'])
    if perm is not None:
        es.append(['permission_exception',perm])
    if not es:
        return ['no_exceptions']
    v=['exception_set',es[0]]
    i=1
    while i<len(es):
        v=['add_exception',v,es[i]]
        i+=1
    return v

def parse_context(raw,ids,out,refs):
    t=raw.casefold()
    if not t:
        return
    if ('“representative” means' in t or '"representative" means' in t or 'representative means' in t) and any_phrase(t,['employee','director','officer','agent','accountant','attorney','contractor']):
        cats=recipient_terms(t)
        fixed=[]
        for c in cats:
            if len(c)>1:
                c[1]=['party']
            fixed.append(c)
        if fixed:
            add_statement(out,['define_representative',['party'],make_union(fixed)],ids)
    if any_phrase(t,['information about employees','employee lists and records','human resources data']) and 'confidential' in t:
        add_statement(out,['confidential_information_includes',['employee_information',['disclosing_party']]],ids)
    if 'whereas' in t and 'may' in t and 'disclos' in t and 'confidential information' in t:
        add_statement(out,['possible_disclosure_description',['disclosing_party'],['confidential_information'],['receiving_party']],ids)
    if 'confidential information' not in t and 'such information' not in t and 'the same' not in t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer agrees' in t else ['receiving_party']
    if 'neither it nor its representatives' in t and any_phrase(t,['any other person','any other organization','other person or organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        ex=make_exceptions(t,None)
        add_statement(out,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],ex],ids)
        return
    pmark=any_phrase(t,['may disclose','may share','internally share','restrict access']) or ('not to disclose' in t and ' except ' in t)
    perm=None
    if pmark:
        seg=permission_segment(t)
        cats=recipient_terms(seg)
        if cats:
            perm=['permission',actor,['disclose',['confidential_information'],make_union(cats)],make_condition(t)]
            add_statement(out,perm,ids)
    third=any_phrase(t,['third parties','third party'])
    neg=any_phrase(t,['shall not disclose','not to disclose','not to, without','not to, directly','not disclose, allow access','not to divulge'])
    if third and neg:
        ex=make_exceptions(t,perm)
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],ids)
        if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
            add_once(refs,'unresolved disclosure cross-reference')

def has_tag(term,name):
    todo=[term]
    while todo:
        x=todo.pop()
        if isinstance(x,list) and x:
            if x[0]==name:
                return True
            i=1
            while i<len(x):
                if isinstance(x[i],list):
                    todo.append(x[i])
                i+=1
    return False

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    statements=[]
    source_output=inputs.get('source_output',{})
    if isinstance(source_output,dict):
        for row in source_output.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(statements,row.get('term'),row.get('support_ids',[]))
    texts=[]
    ids=[]
    for span in spans:
        uid=span.get('id')
        raw=span.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        ids.append(uid)
        texts.append(raw)
        parse_definition(raw,uid,statements)
        parse_disclosure(raw,[uid],statements)
        add_disposal(raw,[uid],statements)
        add_retention(raw,uid,statements)
    i=0
    while i<len(texts):
        current=low(texts[i])
        if (current.endswith(':') and has_any(current,['may disclose','do not apply to the disclosure','shall be handled as follows'])) or (has_any(current,['return of confidential information','shall be returned','returned to']) and not trigger_terms(current)):
            j=i+1
            while j<len(texts) and j<=i+4:
                combined=' '.join(texts[i:j+1])
                support=ids[i:j+1]
                parse_disclosure(combined,support,statements)
                add_disposal(combined,support,statements)
                j+=1
        triggers=trigger_terms(current)
        if triggers and not has_return_action(current) and not has_destroy_action(current):
            floor=max(0,i-3)
            j=i-1
            while j>=floor:
                previous=low(texts[j])
                if has_return_action(previous) or has_destroy_action(previous):
                    add_disposal(texts[j]+' '+texts[i],[ids[j],ids[i]],statements)
                    break
                j-=1
        i+=1
    definitions=False
    unresolved=[]
    for row in statements:
        if isinstance(row.get('term'),list) and row.get('term') and row.get('term')[0]=='define_representative':
            definitions=True
    if not definitions:
        for row in statements:
            term=row.get('term')
            if term_has(term,'representatives_of'):
                unresolved.append('Representatives membership is used by an operative rule but is not defined in the current source output.')
                break
    return {'statements':statements,'complete':len(unresolved)==0,'unresolved':unresolved}

def make_information_bundle(xs):
    if len(xs)==1:
        return xs[0]
    v=xs[len(xs)-1]
    i=len(xs)-2
    while i>=0:
        v=['information_bundle',xs[i],v]
        i-=1
    return v

def disposal_information(t):
    xs=[['confidential_information']]
    if 'copy' in t or 'copies' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['compilation','analysis','derivative work','notes or abstracts','notes and abstracts']):
        xs.append(['derivative_materials_of',['confidential_information']])
    return make_information_bundle(xs)

def retention_information(t):
    xs=[]
    if 'copy' in t or 'copies' in t or 'backup system' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['notes or abstracts','notes and abstracts','compilation','analysis','derivative work']):
        xs.append(['derivative_materials_of',['confidential_information']])
    if not xs:
        xs.append(['confidential_information'])
    return make_information_bundle(xs)

def disposal_trigger(t):
    xs=[]
    if 'termination of service' in t or 'service terminates' in t:
        xs.append(['service_termination'])
    elif any_phrase(t,['upon termination of this agreement','upon termination of the agreement','termination of this agreement']):
        xs.append(['agreement_termination'])
    if 'completion of the purpose' in t:
        xs.append(['purpose_completion'])
    if (('upon' in t and 'request' in t) or 'receipt of a written request' in t or 'written request from' in t or 'written request of' in t):
        xs.append(['request_by',['disclosing_party']])
    if not xs:
        return None
    v=xs[0]
    i=1
    while i<len(xs):
        v=['trigger_alternative',v,xs[i]]
        i+=1
    return v

def retention_condition_for(t):
    if 'required' in t and 'applicable law' in t:
        return ['retention_condition','record copy required by applicable law']
    if 'archival purpose' in t:
        return ['retention_condition','one copy solely for archival purpose']
    if 'single copy' in t and any_phrase(t,['regulatory compliance','compliance with the terms']):
        return ['retention_condition','single copy for regulatory and agreement compliance']
    if 'single copy' in t:
        return ['retention_condition','single copy for the source-stated purpose']
    return ['retention_condition','source-stated limited retention']

def parse_disposal(raw,ids,out):
    t=raw.casefold()
    if not t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer' in t else ['receiving_party']
    explicit_retention=any_phrase(t,['may retain','may maintain a single copy'])
    cond=retention_condition_for(t)
    if explicit_retention:
        add_statement(out,['retention_permission',actor,retention_information(t),['after_disposal'],cond],ids)
    if 'retained' in t and any_phrase(t,['no copies','no copy','no copies, electronic or otherwise']):
        add_statement(out,['retention_prohibition',actor,retention_information(t),['after_disposal']],ids)
    trigger=disposal_trigger(t)
    if trigger is None:
        return
    do_return=re.search(r'\breturn(?:ed|ing)?\b',t,re.I) is not None
    do_destroy=re.search(r'\bdestroy(?:ed|ing)?\b',t,re.I) is not None and 'not destroyed' not in t
    if not do_return and not do_destroy:
        return
    info=disposal_information(t)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    es=[]
    if 'unless otherwise instructed in writing' in t:
